var n=`1290-moqueca-baiana`;var t=`world-1290`;var a=`BR`;var s=`south-america`;var o=4;var r=43;var l={en:`Moqueca Baiana`,ua:`Мокека по-баїянськи`};var m={en:`Moqueca Baiana is a dish from Brazil featuring yellow onion, red bell pepper, tomato, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Мокека по-баїянськи, страва кухні країни Бразилія з такими основними складниками: жовта цибуля, червоний солодкий перець, помідор, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,180,`g`],[`red-bell-pepper`,190,`g`],[`tomato`,360,`g`],[`garlic`,5,`clove`],[`palm-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 13 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 13 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:13,i:[[`coconut-milk`,580,`ml`],[`fish-stock`,300,`ml`],[`cilantro`,30,`g`]]},{en:`Nestle fish and shrimp into the fragrant coconut stew, cover and simmer until fish is opaque (63°C) and shrimp pearly and fully cooked.`,ua:`Покладіть рибу та креветки в ароматне кокосове рагу, накрийте і готуйте до непрозорості риби (63°C) та повної готовності креветок.`,t:[`poaching`],m:16,i:[[`red-snapper`,750,`g`],[`shrimp`,350,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,1,`pcs`]]}];var g={slug:n,id:t,country:`BR`,region:s,servings:4,minutes:43,title:l,text:m,steps:d};export{a as country,g as default,t as id,r as minutes,s as region,o as servings,n as slug,d as steps,m as text,l as title};